def process_graph(graph_data):
    """
    List all the child nodes of a given node.

    :param graph_data: NetworkX graph object
    :return: A JSON object with the result
    """
    def get_children(node_name, graph):
        children = []
        for child in graph.successors(node_name):
            if 'name' in graph.nodes[child]:
                children.append(graph.nodes[child]['name'])
            for grandchild in get_children(child, graph):
                children.append(grandchild)
        return children

    result = {'type': 'list', 'data': get_children('ju1.s4.dom', graph_data), 'updated_graph': nx.readwrite.json_graph.node_link_data(graph_data.copy())}
    return result
