    def get_child_nodes(node_name, graph):
        children = []
        for child in graph.successors(node_name):
            if 'EK_PORT' in graph.nodes[child]['type']:
                children.append((child, graph.nodes[child]['physical_capacity_bps']))
            elif any(block_type in graph.nodes[child]['type'] for block_type in ['EK_AGG_BLOCK', 'EK_RACK']):
                children.extend(get_child_nodes(child, graph))
        return children

    agg_block_node = next((node for node in graph_data.nodes(data=True) if node[0] == 'ju1.a1.m1' and 'EK_AGG_BLOCK' in node[1]['type']), None)
    if not agg_block_node:
        return {'type': 'text', 'data': 'Node of type EK_AGG_BLOCK with name ju1.a1.m1 not found.', 'updated_graph': nx.readwrite.json_graph.node_link_data(graph_data)}

    agg_block_name = agg_block_node[0]
    child_nodes_with_capacity = get_child_nodes(agg_block_name, graph_data)

    sorted_child_nodes = sorted(child_nodes_with_capacity, key=lambda x: x[1], reverse=True)

    return {'type': 'list', 'data': sorted_child_nodes, 'updated_graph': nx.readwrite.json_graph.node_link_data(graph_data)}
