def process_graph(graph_data):
    import networkx as nx

    # Create a copy of the graph to avoid modifying the original graph
    graph_copy = nx.DiGraph(graph_data.copy())

    # Find all EK_AGG_BLOCK nodes
    agg_blocks = [(node, data) for node, data in graph_copy.nodes(data=True) if 'EK_AGG_BLOCK' in data['type']]

    # Initialize a dictionary to store the total physical capacity for each child node
    child_capacity = {}

    # Traverse the graph to calculate the total physical capacity for each child node
    for agg_block in agg_blocks:
        agg_block_name = agg_block[0]
        agg_block_data = agg_block[1]

        # Find all child nodes of the current EK_AGG_BLOCK
        child_nodes = [node for node, data in graph_copy.out_edges(agg_block_name, data=True) if data['type'] == 'RK_CONTAINS']

        for child_node in child_nodes:
            # Follow the hierarchy to find all descendant PORT nodes
            while True:
                child_data = graph_copy.nodes[child_node]
                if 'EK_PORT' in child_data['type']:
                    if child_node not in child_capacity:
                        child_capacity[child_node] = 0
                    child_capacity[child_node] += child_data.get('physical_capacity_bps', 0)

                # Move to the next parent node
                next_parent = None
                for parent, _, data in graph_copy.in_edges(child_node, data=True):
                    if data['type'] == 'RK_CONTAINS':
                        next_parent = parent
                        break

                if next_parent is None:
                    break
                else:
                    child_node = next_parent

    # Sort the child nodes based on their total physical capacity
    sorted_child_capacity = sorted(child_capacity.items(), key=lambda x: x[1], reverse=True)

    # Prepare the return object
    return_object = {
        'type': 'list',
        'data': sorted_child_capacity,
        'updated_graph': nx.readwrite.json_graph.node_link_data(graph_copy)
    }

    return return_object
