def process_graph(graph_data):
    graph_copy = graph_data.copy()
    agg_block_name = 'ju1.a2.m4'
    agg_block_nodes = [node for node in graph_copy.nodes(data=True) if node[0].startswith(agg_block_name) and 'EK_AGG_BLOCK' in node[1]['type']]

    if not agg_block_nodes:
        return {'type': 'text', 'data': 'No EK_AGG_BLOCK node found with the specified name.', 'updated_graph': nx.readwrite.json_graph.node_link_data(graph_copy)}

    agg_block_node = agg_block_nodes[0]
    port_nodes = []
    for node in graph_copy.nodes(data=True):
        if 'EK_PORT' in node[1]['type']:
            port_nodes.append(node)

    port_capacity_sum = {}
    for port_node in port_nodes:
        path_exists = nx.has_path(graph_copy, agg_block_node[0], port_node[0])
        if path_exists:
            paths = nx.all_simple_paths(graph_copy, source=agg_block_node[0], target=port_node[0])
            for path in paths:
                if len(path) > 1:
                    first_edge = graph_copy.get_edge_data(path[0], path[1])
                    if first_edge['type'] == 'RK_CONTAINS':
                        port_name = port_node[0]
                        if port_name not in port_capacity_sum:
                            port_capacity_sum[port_name] = 0
                        port_capacity_sum[port_name] += port_node[1]['physical_capacity_bps']

    sorted_ports = sorted(port_capacity_sum.items(), key=lambda x: x[1], reverse=True)
    return {'type': 'list', 'data': sorted_ports, 'updated_graph': nx.readwrite.json_graph.node_link_data(graph_copy)}
