    target_node = None
    for node in graph_copy.nodes(data=True):
        if node[0].startswith('ju1.s4.dom') and 'EK_CONTROL_DOMAIN' in node[1]['type']:
            target_node = node[0]
            break

    if target_node is None:
        return {'type': 'text', 'data': 'Target node not found.', 'updated_graph': nx.readwrite.json_graph.node_link_data(graph_copy)}

    # Add new_EK_PACKET_SWITCH_33 to ju1.s4.dom
    new_packet_switch_name = 'new_EK_PACKET_SWITCH_33'
    graph_copy.add_node(new_packet_switch_name, name=new_packet_switch_name, type=['EK_PACKET_SWITCH'])
    graph_copy.add_edge(target_node, new_packet_switch_name, type='RK_CONTAINS')

    # Count the EK_PACKET_SWITCH in ju1.s4.dom
    packet_switch_count = 0
    for node in graph_copy.nodes(data=True):
