    parent_node = None
    for node in graph_copy.nodes(data=True):
        if node[0].startswith(parent_node_name) and 'EK_CONTROL_DOMAIN' in node[1]['type']:
            parent_node = node[0]
            break

    if parent_node is None:
        return {'type': 'text', 'data': 'Parent node not found.', 'updated_graph': nx.readwrite.json_graph.node_link_data(graph_copy)}

    # Create new port node
    new_port_name = 'new_EK_PORT_88'
    new_port_type = ['EK_PORT']
    new_port_attributes = {'name': new_port_name, 'type': new_port_type, 'physical_capacity_bps': 1000000000}
    graph_copy.add_node(new_port_name, **new_port_attributes)

    # Add edge from parent node to new port node
    graph_copy.add_edge(parent_node, new_port_name, type='RK_CONTAINS')

    # Collect all direct child nodes of parent_node
    direct_child_nodes = []
    for child in graph_copy.successors(parent_node):
        if graph_copy.edges[parent_node, child]['type'] == 'RK_CONTAINS':
            direct_child_nodes.append(child)

    # Calculate total physical capacity for each direct child node
    capacity_dict = {}
    for node in direct_child_nodes:
        if 'EK_PORT' in graph_copy.nodes[node]['type']:
            capacity_dict[node] = graph_copy.nodes[node].get('physical_capacity_bps', 0)
        else:
            port_nodes = [n for n in graph_copy.nodes() if graph_copy.nodes[n]['name'].startswith(node) and 'EK_PORT' in graph_copy.nodes[n]['type']]
            total_capacity = sum(graph_copy.nodes[port]['physical_capacity_bps'] for port in port_nodes)
            capacity_dict[node] = total_capacity

    # Sort nodes based on total physical capacity
    sorted_nodes = sorted(capacity_dict.items(), key=lambda x: x[1], reverse=True)

    return {'type': 'list', 'data': sorted_nodes, 'updated_graph': nx.readwrite.json_graph.node_link_data(graph_copy)}
